SELECT * FROM (SELECT e.event_id,'C:'||s.action_id case_id,e.activity,e.timestamp FROM (SELECT 'C:'||action_id event_id,'Request Checked' activity,occurred_at timestamp,action_id source_key FROM request_action WHERE occurred_at IS NOT NULL AND (action_code='A')) e JOIN request_action s ON s.action_id=e.source_key WHERE s.action_id IS NOT NULL UNION ALL SELECT e.event_id,'C:'||s.action_id case_id,e.activity,e.timestamp FROM (SELECT 'C:'||action_id event_id,'Request Held' activity,occurred_at timestamp,action_id source_key FROM request_action WHERE occurred_at IS NOT NULL AND (action_code='H')) e JOIN request_action s ON s.action_id=e.source_key WHERE s.action_id IS NOT NULL UNION ALL SELECT e.event_id,'C:'||s.action_id case_id,e.activity,e.timestamp FROM (SELECT 'C:'||action_id event_id,'Request Released' activity,occurred_at timestamp,action_id source_key FROM request_action WHERE occurred_at IS NOT NULL AND (action_code='R')) e JOIN request_action s ON s.action_id=e.source_key WHERE s.action_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
